-- V4_3__insert_itinerarios_2076_9051_mocks.sql
-- Cadastra linha 2076-10 e itinerarios no sentido IDA para 2076-10 e 9051-10

DO $$
DECLARE
    v_linha_2076_id BIGINT;
    v_rota_2076_ida_id BIGINT;
    v_linha_9051_id BIGINT;
    v_rota_9051_ida_id BIGINT;
    v_parada_id BIGINT;
BEGIN
    -- 1. Obter ou Criar Linha 2076-10
    SELECT LIN_LINHA_ID INTO v_linha_2076_id FROM T_LIN_LINHA WHERE LIN_LINHA_CODIGO = '2076' AND LIN_LINHA_ATENDIMENTO = '10' AND GLB_MUNICIPIO_COD = 3550308;
    IF v_linha_2076_id IS NULL THEN
        VALUES ('2076', '10', 'TERMINAL PENHA - JD. DAS OLIVEIRAS', 3550308, 1, 'N', 'N', 'S', 'S')
        RETURNING LIN_LINHA_ID INTO v_linha_2076_id;
    END IF;

    -- 2. Rota 2076-10 IDA
    SELECT LIN_ROTA_ID INTO v_rota_2076_ida_id FROM T_LIN_ROTA WHERE LIN_LINHA_ID = v_linha_2076_id AND LIN_ROTA_SENTIDO = 'IDA';
    IF v_rota_2076_ida_id IS NULL THEN
        VALUES (v_linha_2076_id, 'JD. DAS OLIVEIRAS', 'IDA')
        RETURNING LIN_ROTA_ID INTO v_rota_2076_ida_id;
    ELSE
        UPDATE T_LIN_ROTA SET LIN_ROTA_PREFIXO = 'JD. DAS OLIVEIRAS' WHERE LIN_ROTA_ID = v_rota_2076_ida_id;
    END IF;
    DELETE FROM T_LIN_ITINERARIO WHERE LIN_ROTA_ID = v_rota_2076_ida_id;

    -- 3. Paradas e Itinerario 2076-10

    -- 4. Linha 9051-10 e Rota IDA
    SELECT LIN_LINHA_ID INTO v_linha_9051_id FROM T_LIN_LINHA WHERE LIN_LINHA_CODIGO = '9051' AND LIN_LINHA_ATENDIMENTO = '10' AND GLB_MUNICIPIO_COD = 3550308;
    SELECT LIN_ROTA_ID INTO v_rota_9051_ida_id FROM T_LIN_ROTA WHERE LIN_LINHA_ID = v_linha_9051_id AND LIN_ROTA_SENTIDO = 'IDA';
    IF v_rota_9051_ida_id IS NULL THEN
        VALUES (v_linha_9051_id, 'TERM. LAPA', 'IDA')
        RETURNING LIN_ROTA_ID INTO v_rota_9051_ida_id;
    ELSE
        UPDATE T_LIN_ROTA SET LIN_ROTA_PREFIXO = 'TERM. LAPA' WHERE LIN_ROTA_ID = v_rota_9051_ida_id;
    END IF;
    DELETE FROM T_LIN_ITINERARIO WHERE LIN_ROTA_ID = v_rota_9051_ida_id;

    -- 5. Paradas e Itinerario 9051-10
END $$;

SELECT setval(pg_get_serial_sequence('T_LIN_LINHA', 'lin_linha_id'), coalesce(max(lin_linha_id), 1)) FROM T_LIN_LINHA;
SELECT setval(pg_get_serial_sequence('T_LIN_ROTA', 'lin_rota_id'), coalesce(max(lin_rota_id), 1)) FROM T_LIN_ROTA;
SELECT setval(pg_get_serial_sequence('T_LIN_PARADA', 'lin_parada_id'), coalesce(max(lin_parada_id), 1)) FROM T_LIN_PARADA;
SELECT setval(pg_get_serial_sequence('T_LIN_ITINERARIO', 'lin_itinerario_id'), coalesce(max(lin_itinerario_id), 1)) FROM T_LIN_ITINERARIO;
